import { text, integer, json, timestamp } from '@keystone-6/core/fields';
import { domainList, name, state, money, currency, rel } from './domainFields';
export const Guide = domainList('canManageGuides', { name: name(), user: rel('User.guide'), languages: json({ defaultValue: ['English'] }), certifications: rel('GuideCertification.guide', true), payRateType: state(['per_tour','hourly']), payRateCents: money(), currencyCode: currency(), status: state(['active','inactive']), photo: text(), bio: text(), availability: rel('GuideAvailability.guide', true), assignments: rel('GuideAssignment.guide', true), payouts: rel('GuidePayout.guide', true) });
export const GuideCertification = domainList('canManageGuides', { name: name(), guide: rel('Guide.certifications'), expiresAt: timestamp(), reference: text() });
export const GuideAvailability = domainList('canManageGuides', { guide: rel('Guide.availability'), startAt: timestamp(), endAt: timestamp(), weeklyRules: json(), unavailable: json({ defaultValue: [] }) });
export const GuideAssignment = domainList('canManageGuides', { departure: rel('Departure.assignedGuides'), guide: rel('Guide.assignments'), role: state(['lead','assistant','driver']), status: state(['offered','accepted','declined','cancelled','worked']), payCents: money(), currencyCode: currency(), payout: rel('GuidePayout.assignments') }, true);
export const Resource = domainList('canManageResources', { name: name(), kind: state(['van','kayak','bike','boat']), seats: integer({ defaultValue: 1, validation: { min: 1 } }), quantity: integer({ defaultValue: 1, validation: { min: 1 } }), status: state(['active','maintenance']), assignments: rel('ResourceAssignment.resource', true) });
export const ResourceAssignment = domainList('canManageResources', { departure: rel('Departure.resourceAssignments'), resource: rel('Resource.assignments'), quantity: integer({ defaultValue: 1, validation: { min: 1 } }) }, true);
export const GuidePayout = domainList('canManageGuides', { guide: rel('Guide.payouts'), periodStart: timestamp(), periodEnd: timestamp(), assignments: rel('GuideAssignment.payout', true), totalCents: money(), currencyCode: currency(), status: state(['draft','approved','paid']), paidAt: timestamp(), reference: text() }, true);
